#!/usr/bin/env node
import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import process from "node:process";
import { fileURLToPath } from "node:url";

const SCRIPT_DIR = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(SCRIPT_DIR, "..");
const COMPONENT_DIR = path.join(ROOT, "packages/gooey/src/components/ui");
const TOKEN_CSS = path.join(ROOT, "packages/gooey/src/styles/design-tokens.css");
const DEFAULT_OUT = path.join(ROOT, "swift/GooeySwift");

const GENERATED_HEADER = [
  "// Generated by scripts/convert-gooey-swift.mjs.",
  "// Source of truth: packages/gooey/src/styles/design-tokens.css and packages/gooey/src/components/ui.",
  "// Re-run the converter instead of editing generated files directly.",
  "",
].join("\n");

const SUPPORTED_COMPONENTS = new Map([
  ["button", { target: "GooeyControls", file: "GooeyButton.swift", render: renderButton }],
  ["icon-only-button", { target: "GooeyControls", file: "GooeyIconButton.swift", render: renderIconOnlyButton }],
  ["badge", { target: "GooeyControls", file: "GooeyBadge.swift", render: renderBadge }],
  ["switch", { target: "GooeyControls", file: "GooeySwitch.swift", render: renderSwitch }],
  ["checkbox", { target: "GooeyControls", file: "GooeyCheckbox.swift", render: renderCheckbox }],
  ["radio", { target: "GooeyControls", file: "GooeyRadio.swift", render: renderRadio }],
  ["input", { target: "GooeyControls", file: "GooeyInput.swift", render: renderInput }],
  ["card", { target: "GooeyPatterns", file: "GooeyCard.swift", render: renderCard }],
  ["skeleton", { target: "GooeyPatterns", file: "GooeySkeleton.swift", render: renderSkeleton }],
]);

function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.help) {
    printHelp();
    return;
  }

  assertRepoShape();

  const components = listComponents();
  const selected = selectComponents(components, args);
  const tokenSets = parseDesignTokens(readFileSync(TOKEN_CSS, "utf8"));
  const conversion = buildConversionPlan(components, selected);

  if (args.list) {
    printComponentList(conversion);
    return;
  }

  const outDir = path.resolve(ROOT, args.out ?? DEFAULT_OUT);
  const writes = new Map();

  addPackageFiles(writes, outDir);
  addTokenFiles(writes, outDir, tokenSets);
  addFoundationFiles(writes, outDir);
  addSelectedComponents(writes, outDir, selected);
  addReport(writes, outDir, conversion, selected, tokenSets);

  if (args.dryRun) {
    printDryRun(writes, conversion, selected, outDir);
    return;
  }

  writeAll(writes, { force: args.force });
  printSummary(conversion, selected, outDir);
}

function parseArgs(argv) {
  const args = {
    component: [],
    allSupported: false,
    dryRun: false,
    force: false,
    list: false,
    help: false,
    out: undefined,
  };

  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (arg === "--help" || arg === "-h") args.help = true;
    else if (arg === "--list") args.list = true;
    else if (arg === "--all-supported") args.allSupported = true;
    else if (arg === "--dry-run") args.dryRun = true;
    else if (arg === "--force") args.force = true;
    else if (arg === "--out") args.out = requireValue(argv, ++i, "--out");
    else if (arg === "--component") args.component.push(slugify(requireValue(argv, ++i, "--component")));
    else fail(`Unknown argument: ${arg}`);
  }

  return args;
}

function requireValue(argv, index, flag) {
  const value = argv[index];
  if (!value || value.startsWith("--")) fail(`${flag} requires a value`);
  return value;
}

function printHelp() {
  console.log(`Gooey Swift incremental converter

Usage:
  node scripts/convert-gooey-swift.mjs --list
  node scripts/convert-gooey-swift.mjs --component button --dry-run
  node scripts/convert-gooey-swift.mjs --component button --component badge
  node scripts/convert-gooey-swift.mjs --all-supported
  node scripts/convert-gooey-swift.mjs --all-supported --force

Rules:
  - Converts only components with explicit SwiftUI templates.
  - Generates a report for unsupported components.
  - Does not overwrite existing generated files unless --force is passed.
  - Uses design-tokens.css as the token source.
`);
}

function assertRepoShape() {
  for (const required of [COMPONENT_DIR, TOKEN_CSS]) {
    if (!existsSync(required)) {
      fail(`Missing required path: ${path.relative(ROOT, required)}`);
    }
  }
}

function listComponents() {
  return readdirSync(COMPONENT_DIR)
    .filter((file) => file.endsWith(".tsx"))
    .map((file) => file.replace(/\.tsx$/, ""))
    .sort((a, b) => a.localeCompare(b));
}

function selectComponents(components, args) {
  if (args.allSupported) {
    return components.filter((name) => SUPPORTED_COMPONENTS.has(name));
  }

  if (args.component.length === 0) {
    return [];
  }

  const known = new Set(components);
  for (const name of args.component) {
    if (!known.has(name)) fail(`Component not found: ${name}`);
    if (!SUPPORTED_COMPONENTS.has(name)) {
      fail(`Component is not template-supported yet: ${name}`);
    }
  }

  return [...new Set(args.component)].sort((a, b) => a.localeCompare(b));
}

function buildConversionPlan(components, selected) {
  const selectedSet = new Set(selected);
  return components.map((name) => {
    const support = SUPPORTED_COMPONENTS.get(name);
    return {
      id: name,
      source: `packages/gooey/src/components/ui/${name}.tsx`,
      status: support ? (selectedSet.has(name) ? "converted" : "template-ready") : "needs-template",
      target: support?.target ?? null,
      swiftFile: support ? `swift/GooeySwift/Sources/${support.target}/${support.file}` : null,
      reason: support
        ? "Native SwiftUI template exists."
        : classifyUnsupportedComponent(name),
    };
  });
}

function classifyUnsupportedComponent(name) {
  if (["dynamic-island", "prompt-bar", "bottom-bar", "tray", "library-menu"].includes(name)) {
    return "State-machine component. Convert after manifest models and enum states exist.";
  }
  if (["badge-drop-zone", "fireworks", "pet", "custom-cursor", "lordicon", "react"].includes(name)) {
    return "Runtime/effect component. Requires a native adapter before SwiftUI output.";
  }
  if (name.includes("avatar") || name.includes("image") || name.includes("photo")) {
    return "Asset component. Requires typed GooeyAsset ids and Swift asset catalog mapping.";
  }
  return "Needs an explicit SwiftUI template before conversion is safe.";
}

function parseDesignTokens(css) {
  const rootBlock = extractCssBlock(css, ":root");
  const lightBlock = extractCssBlock(css, ":root.light");

  return {
    dark: parseColorVariables(rootBlock),
    light: parseColorVariables(lightBlock),
  };
}

function extractCssBlock(css, selector) {
  const start = css.indexOf(`${selector} {`);
  if (start === -1) return "";
  let depth = 0;
  let bodyStart = -1;
  for (let i = start; i < css.length; i += 1) {
    if (css[i] === "{") {
      depth += 1;
      if (bodyStart === -1) bodyStart = i + 1;
    } else if (css[i] === "}") {
      depth -= 1;
      if (depth === 0) return css.slice(bodyStart, i);
    }
  }
  return "";
}

function parseColorVariables(block) {
  const colors = {};
  const re = /--color-([a-z0-9-]+):\s*([^;]+);/g;
  let match;
  while ((match = re.exec(block))) {
    const name = match[1];
    const value = match[2].trim();
    if (isSupportedColorValue(value)) {
      colors[name] = value;
    }
  }
  return colors;
}

function isSupportedColorValue(value) {
  return /^#[0-9a-fA-F]{6,8}$/.test(value) || /^rgba?\(/.test(value);
}

function addPackageFiles(writes, outDir) {
  setWrite(writes, path.join(outDir, "Package.swift"), `// swift-tools-version: 6.0
${GENERATED_HEADER}import PackageDescription

let package = Package(
  name: "GooeySwift",
  platforms: [
    .iOS(.v17),
    .macOS(.v14)
  ],
  products: [
    .library(
      name: "GooeySwift",
      targets: [
        "GooeyTokens",
        "GooeyFoundation",
        "GooeyControls",
        "GooeyPatterns",
        "GooeyPreviewSupport"
      ]
    )
  ],
  targets: [
    .target(name: "GooeyTokens"),
    .target(name: "GooeyFoundation", dependencies: ["GooeyTokens"]),
    .target(name: "GooeyControls", dependencies: ["GooeyTokens", "GooeyFoundation"]),
    .target(name: "GooeyPatterns", dependencies: ["GooeyTokens", "GooeyFoundation", "GooeyControls"]),
    .target(name: "GooeyPreviewSupport", dependencies: ["GooeyTokens", "GooeyFoundation", "GooeyControls", "GooeyPatterns"])
  ]
)
`);
}

function addTokenFiles(writes, outDir, tokenSets) {
  setWrite(writes, path.join(outDir, "Sources/GooeyTokens/GooeyTokens.swift"), renderTokens(tokenSets));
}

function renderTokens(tokenSets) {
  const darkEntries = renderTokenDictionary(tokenSets.dark);
  const lightEntries = renderTokenDictionary(tokenSets.light);

  return `${GENERATED_HEADER}import SwiftUI

public enum GooeyThemeMode: String, Sendable {
  case dark
  case light
  case system
}

public enum GooeyResolvedColorScheme: String, Sendable {
  case dark
  case light
}

public enum GooeyTokenColor: Hashable, Sendable {
  case hex(String)
  case rgba(red: Double, green: Double, blue: Double, alpha: Double)
}

public enum GooeyTokens {
  public static let darkColors: [String: GooeyTokenColor] = [
${darkEntries}
  ]

  public static let lightColors: [String: GooeyTokenColor] = [
${lightEntries}
  ]

  public static func tokenColor(_ name: String, scheme: GooeyResolvedColorScheme) -> GooeyTokenColor {
    let table = scheme == .light ? lightColors : darkColors
    if let value = table[name] {
      return value
    }
    if let fallback = darkColors[name] {
      return fallback
    }
    return .hex("#FF00EE")
  }

  public static func color(_ name: String, scheme: GooeyResolvedColorScheme) -> Color {
    Color(tokenColor(name, scheme: scheme))
  }
}

public extension Color {
  init(_ tokenColor: GooeyTokenColor) {
    switch tokenColor {
    case .hex(let hex):
      self.init(hex: hex)
    case .rgba(let red, let green, let blue, let alpha):
      self.init(.sRGB, red: red, green: green, blue: blue, opacity: alpha)
    }
  }

  init(hex: String) {
    let trimmed = hex.trimmingCharacters(in: CharacterSet.alphanumerics.inverted)
    var value: UInt64 = 0
    Scanner(string: trimmed).scanHexInt64(&value)

    let red: UInt64
    let green: UInt64
    let blue: UInt64
    let alpha: UInt64

    switch trimmed.count {
    case 8:
      red = (value & 0xff000000) >> 24
      green = (value & 0x00ff0000) >> 16
      blue = (value & 0x0000ff00) >> 8
      alpha = value & 0x000000ff
    case 6:
      red = (value & 0xff0000) >> 16
      green = (value & 0x00ff00) >> 8
      blue = value & 0x0000ff
      alpha = 255
    default:
      red = 255
      green = 0
      blue = 238
      alpha = 255
    }

    self.init(
      .sRGB,
      red: Double(red) / 255,
      green: Double(green) / 255,
      blue: Double(blue) / 255,
      opacity: Double(alpha) / 255
    )
  }
}
`;
}

function renderTokenDictionary(tokens) {
  return Object.entries(tokens)
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([name, value]) => `    "${name}": ${swiftTokenColor(value)},`)
    .join("\n");
}

function swiftTokenColor(value) {
  if (value.startsWith("#")) return `.hex("${value.toUpperCase()}")`;

  const rgba = value.match(/^rgba?\(([^)]+)\)$/);
  if (!rgba) return `.hex("#FF00EE")`;
  const parts = rgba[1].split(",").map((part) => part.trim());
  const red = clamp(Number(parts[0]) / 255, 0, 1);
  const green = clamp(Number(parts[1]) / 255, 0, 1);
  const blue = clamp(Number(parts[2]) / 255, 0, 1);
  const alpha = parts[3] === undefined ? 1 : clamp(Number(parts[3]), 0, 1);
  return `.rgba(red: ${formatNumber(red)}, green: ${formatNumber(green)}, blue: ${formatNumber(blue)}, alpha: ${formatNumber(alpha)})`;
}

function clamp(value, min, max) {
  if (!Number.isFinite(value)) return min;
  return Math.min(max, Math.max(min, value));
}

function formatNumber(value) {
  return Number(value.toFixed(4)).toString();
}

function addFoundationFiles(writes, outDir) {
  setWrite(writes, path.join(outDir, "Sources/GooeyFoundation/GooeyFoundation.swift"), renderFoundation());
  setWrite(writes, path.join(outDir, "Sources/GooeyPreviewSupport/GooeyPreviewSupport.swift"), renderPreviewSupport());
}

function renderFoundation() {
  return `${GENERATED_HEADER}import SwiftUI
import GooeyTokens

public struct GooeyTheme: Sendable {
  public var mode: GooeyThemeMode
  public var resolvedScheme: GooeyResolvedColorScheme

  public init(mode: GooeyThemeMode = .dark, resolvedScheme: GooeyResolvedColorScheme = .dark) {
    self.mode = mode
    self.resolvedScheme = resolvedScheme
  }

  public func color(_ token: String) -> Color {
    GooeyTokens.color(token, scheme: resolvedScheme)
  }
}

private struct GooeyThemeKey: EnvironmentKey {
  static let defaultValue = GooeyTheme()
}

public extension EnvironmentValues {
  var gooeyTheme: GooeyTheme {
    get { self[GooeyThemeKey.self] }
    set { self[GooeyThemeKey.self] = newValue }
  }
}

public enum GooeyViewport: String, Sendable {
  case phone
  case tablet
  case desktop
  case wide
}

public enum GooeyViewportResolver {
  public static func resolve(width: CGFloat) -> GooeyViewport {
    if width >= 1440 { return .wide }
    if width >= 1024 { return .desktop }
    if width >= 600 { return .tablet }
    return .phone
  }
}

public struct GooeyHaptics: Sendable {
  public var light: @Sendable () -> Void
  public var medium: @Sendable () -> Void
  public var heavy: @Sendable () -> Void
  public var success: @Sendable () -> Void
  public var error: @Sendable () -> Void
  public var warning: @Sendable () -> Void
  public var selection: @Sendable () -> Void

  public init(
    light: @escaping @Sendable () -> Void = {},
    medium: @escaping @Sendable () -> Void = {},
    heavy: @escaping @Sendable () -> Void = {},
    success: @escaping @Sendable () -> Void = {},
    error: @escaping @Sendable () -> Void = {},
    warning: @escaping @Sendable () -> Void = {},
    selection: @escaping @Sendable () -> Void = {}
  ) {
    self.light = light
    self.medium = medium
    self.heavy = heavy
    self.success = success
    self.error = error
    self.warning = warning
    self.selection = selection
  }
}

private struct GooeyHapticsKey: EnvironmentKey {
  static let defaultValue = GooeyHaptics()
}

public extension EnvironmentValues {
  var gooeyHaptics: GooeyHaptics {
    get { self[GooeyHapticsKey.self] }
    set { self[GooeyHapticsKey.self] = newValue }
  }
}

public struct GooeyGlassPill: ViewModifier {
  @Environment(\\.gooeyTheme) private var theme

  public var radius: CGFloat
  public var borderWidth: CGFloat

  public init(radius: CGFloat = 999, borderWidth: CGFloat = 2) {
    self.radius = radius
    self.borderWidth = borderWidth
  }

  public func body(content: Content) -> some View {
    content
      .background(theme.color("light-glass-5"))
      .clipShape(RoundedRectangle(cornerRadius: radius, style: .continuous))
      .overlay {
        RoundedRectangle(cornerRadius: radius, style: .continuous)
          .stroke(theme.color("light-glass-20"), lineWidth: borderWidth)
      }
      .shadow(color: .black.opacity(0.1), radius: 4, y: 1)
  }
}

public extension View {
  func gooeyGlassPill(radius: CGFloat = 999, borderWidth: CGFloat = 2) -> some View {
    modifier(GooeyGlassPill(radius: radius, borderWidth: borderWidth))
  }
}
`;
}

function renderPreviewSupport() {
  return `${GENERATED_HEADER}import SwiftUI
import GooeyFoundation

public enum GooeyPreviewMatrix {
  public static let themes: [GooeyTheme] = [
    GooeyTheme(mode: .dark, resolvedScheme: .dark),
    GooeyTheme(mode: .light, resolvedScheme: .light)
  ]

  public static let viewports: [GooeyViewport] = [
    .phone,
    .tablet,
    .desktop,
    .wide
  ]
}
`;
}

function addSelectedComponents(writes, outDir, selected) {
  for (const component of selected) {
    const support = SUPPORTED_COMPONENTS.get(component);
    setWrite(
      writes,
      path.join(outDir, "Sources", support.target, support.file),
      support.render(),
    );
  }
}

function renderButton() {
  return `${GENERATED_HEADER}import SwiftUI
import GooeyFoundation

public enum GooeyButtonVariant: String, CaseIterable, Sendable {
  case primary
  case secondary
  case destructive
  case ghost
  case link
  case secondaryNeutral
  case primaryNeutral
  case destructiveNeutral
}

public enum GooeyButtonSize: Sendable {
  case small
  case regular
  case large
  case extraLarge
  case icon

  var height: CGFloat {
    switch self {
    case .small: return 32
    case .regular: return 36
    case .large: return 40
    case .extraLarge: return 50
    case .icon: return 36
    }
  }

  var horizontalPadding: CGFloat {
    switch self {
    case .small: return 12
    case .regular: return 16
    case .large: return 24
    case .extraLarge: return 20
    case .icon: return 0
    }
  }

  var cornerRadius: CGFloat {
    switch self {
    case .small, .large: return 8
    case .regular, .icon: return 12
    case .extraLarge: return 999
    }
  }
}

public struct GooeyButton: View {
  public var title: String
  public var systemImage: String?
  public var variant: GooeyButtonVariant
  public var size: GooeyButtonSize
  public var isDisabled: Bool
  public var action: () -> Void

  @Environment(\\.gooeyHaptics) private var haptics

  public init(
    _ title: String,
    systemImage: String? = nil,
    variant: GooeyButtonVariant = .primary,
    size: GooeyButtonSize = .regular,
    isDisabled: Bool = false,
    action: @escaping () -> Void
  ) {
    self.title = title
    self.systemImage = systemImage
    self.variant = variant
    self.size = size
    self.isDisabled = isDisabled
    self.action = action
  }

  public var body: some View {
    Button {
      haptics.light()
      action()
    } label: {
      HStack(spacing: systemImage == nil ? 0 : 8) {
        if let systemImage {
          Image(systemName: systemImage)
        }
        Text(title)
      }
    }
    .buttonStyle(GooeyButtonStyle(variant: variant, size: size))
    .disabled(isDisabled)
  }
}

public struct GooeyButtonStyle: ButtonStyle {
  public var variant: GooeyButtonVariant
  public var size: GooeyButtonSize

  @Environment(\\.gooeyTheme) private var theme
  @Environment(\\.accessibilityReduceMotion) private var reduceMotion
  @Environment(\\.isEnabled) private var isEnabled

  public init(variant: GooeyButtonVariant = .primary, size: GooeyButtonSize = .regular) {
    self.variant = variant
    self.size = size
  }

  public func makeBody(configuration: Configuration) -> some View {
    configuration.label
      .font(.system(size: 14, weight: .semibold, design: .rounded))
      .frame(minWidth: size == .icon ? size.height : nil)
      .frame(height: size.height)
      .padding(.horizontal, size.horizontalPadding)
      .foregroundStyle(foregroundColor(isPressed: configuration.isPressed))
      .background(backgroundColor(isPressed: configuration.isPressed))
      .clipShape(RoundedRectangle(cornerRadius: size.cornerRadius, style: .continuous))
      .overlay {
        RoundedRectangle(cornerRadius: size.cornerRadius, style: .continuous)
          .stroke(borderColor(isPressed: configuration.isPressed), lineWidth: borderWidth)
      }
      .shadow(color: shadowColor, radius: shadowRadius, y: shadowY)
      .scaleEffect(configuration.isPressed && !reduceMotion ? 0.98 : 1)
      .opacity(isEnabled ? 1 : 0.4)
      .animation(reduceMotion ? nil : .spring(response: 0.22, dampingFraction: 0.8), value: configuration.isPressed)
  }

  private var borderWidth: CGFloat {
    switch variant {
    case .secondaryNeutral, .destructiveNeutral: return 2
    default: return 0
    }
  }

  private var shadowColor: Color {
    variant == .link || variant == .ghost ? .clear : .black.opacity(0.12)
  }

  private var shadowRadius: CGFloat {
    variant == .link || variant == .ghost ? 0 : 4
  }

  private var shadowY: CGFloat {
    variant == .link || variant == .ghost ? 0 : 2
  }

  private func foregroundColor(isPressed: Bool) -> Color {
    switch variant {
    case .primary, .primaryNeutral:
      return isPressed ? theme.color("light-space") : theme.color("dark-space")
    case .destructive:
      return theme.color("dark-space")
    case .destructiveNeutral:
      return isPressed ? theme.color("dark-space") : theme.color("red-4")
    case .secondary, .secondaryNeutral, .ghost:
      return isPressed ? theme.color("dark-space") : theme.color("light-space")
    case .link:
      return theme.color("purple-4")
    }
  }

  private func backgroundColor(isPressed: Bool) -> Color {
    switch variant {
    case .primary:
      return isPressed ? theme.color("purple-5") : theme.color("purple-4")
    case .primaryNeutral:
      return isPressed ? theme.color("dark-space") : theme.color("light-space")
    case .secondary:
      return isPressed ? theme.color("smoke-3") : theme.color("smoke-2")
    case .secondaryNeutral:
      return isPressed ? theme.color("light-space") : theme.color("light-glass-5")
    case .destructive:
      return isPressed ? theme.color("red-5") : theme.color("red-4")
    case .destructiveNeutral:
      return isPressed ? theme.color("light-space") : theme.color("red-1")
    case .ghost, .link:
      return isPressed ? theme.color("light-glass-10") : .clear
    }
  }

  private func borderColor(isPressed: Bool) -> Color {
    switch variant {
    case .secondaryNeutral:
      return isPressed ? theme.color("light-glass-5") : theme.color("light-glass-20")
    case .destructiveNeutral:
      return isPressed ? .clear : theme.color("red-4")
    default:
      return .clear
    }
  }
}
`;
}

function renderIconOnlyButton() {
  return `${GENERATED_HEADER}import SwiftUI
import GooeyFoundation

public enum GooeyIconButtonVariant: Sendable {
  case neutral
  case primary
}

public enum GooeyIconButtonSize: Sendable {
  case small
  case medium
  case large

  var dimension: CGFloat {
    switch self {
    case .small: return 40
    case .medium: return 50
    case .large: return 64
    }
  }
}

public struct GooeyIconButton<Icon: View>: View {
  public var label: String
  public var variant: GooeyIconButtonVariant
  public var size: GooeyIconButtonSize
  public var isDisabled: Bool
  public var action: () -> Void
  public var icon: Icon

  @Environment(\\.gooeyTheme) private var theme
  @Environment(\\.gooeyHaptics) private var haptics
  @Environment(\\.accessibilityReduceMotion) private var reduceMotion

  public init(
    label: String,
    variant: GooeyIconButtonVariant = .neutral,
    size: GooeyIconButtonSize = .medium,
    isDisabled: Bool = false,
    action: @escaping () -> Void,
    @ViewBuilder icon: () -> Icon
  ) {
    self.label = label
    self.variant = variant
    self.size = size
    self.isDisabled = isDisabled
    self.action = action
    self.icon = icon()
  }

  public var body: some View {
    Button {
      haptics.light()
      action()
    } label: {
      icon
        .frame(width: iconSize, height: iconSize)
        .frame(width: size.dimension, height: size.dimension)
    }
    .buttonStyle(PlainButtonStyle())
    .foregroundStyle(foreground)
    .background(background)
    .clipShape(Circle())
    .overlay {
      Circle().stroke(border, lineWidth: 2)
    }
    .shadow(color: .black.opacity(0.1), radius: 4, y: 1)
    .disabled(isDisabled)
    .opacity(isDisabled ? 0.5 : 1)
    .accessibilityLabel(Text(label))
    .animation(reduceMotion ? nil : .spring(response: 0.2, dampingFraction: 0.85), value: isDisabled)
  }

  private var iconSize: CGFloat {
    switch size {
    case .small: return 18
    case .medium: return 22
    case .large: return 28
    }
  }

  private var foreground: Color {
    switch variant {
    case .primary: return theme.color("dark-space")
    case .neutral: return theme.color("light-space")
    }
  }

  private var background: Color {
    switch variant {
    case .primary: return theme.color("light-space")
    case .neutral: return theme.color("light-glass-5")
    }
  }

  private var border: Color {
    switch variant {
    case .primary: return theme.color("light-glass-20")
    case .neutral: return theme.color("light-glass-20")
    }
  }
}

public extension GooeyIconButton where Icon == Image {
  init(
    label: String,
    systemName: String,
    variant: GooeyIconButtonVariant = .neutral,
    size: GooeyIconButtonSize = .medium,
    isDisabled: Bool = false,
    action: @escaping () -> Void
  ) {
    self.init(label: label, variant: variant, size: size, isDisabled: isDisabled, action: action) {
      Image(systemName: systemName)
    }
  }
}
`;
}

function renderBadge() {
  return `${GENERATED_HEADER}import SwiftUI
import GooeyFoundation

public enum GooeyBadgeColor: String, CaseIterable, Sendable {
  case red
  case blue
  case green
  case yellow
  case purple
  case neutral
}

public enum GooeyBadgeVariant: Sendable {
  case outline
  case filled
}

public enum GooeyBadgeSize: Sendable {
  case regular
  case tag

  var height: CGFloat {
    switch self {
    case .regular: return 24
    case .tag: return 32
    }
  }

  var horizontalPadding: CGFloat {
    switch self {
    case .regular: return 10
    case .tag: return 12
    }
  }
}

public struct GooeyBadge: View {
  public var label: String
  public var color: GooeyBadgeColor
  public var variant: GooeyBadgeVariant
  public var size: GooeyBadgeSize
  public var systemImage: String?

  @Environment(\\.gooeyTheme) private var theme

  public init(
    _ label: String,
    color: GooeyBadgeColor = .neutral,
    variant: GooeyBadgeVariant = .outline,
    size: GooeyBadgeSize = .regular,
    systemImage: String? = nil
  ) {
    self.label = label
    self.color = color
    self.variant = variant
    self.size = size
    self.systemImage = systemImage
  }

  public var body: some View {
    HStack(spacing: systemImage == nil ? 0 : 4) {
      if let systemImage {
        Image(systemName: systemImage)
          .font(.system(size: 12, weight: .medium))
      }
      Text(label)
    }
    .font(.system(size: 12, weight: .regular, design: .monospaced))
    .lineLimit(1)
    .frame(height: size.height)
    .padding(.horizontal, size.horizontalPadding)
    .foregroundStyle(foreground)
    .background(background)
    .clipShape(Capsule())
    .overlay {
      Capsule().stroke(border, lineWidth: 1)
    }
    .shadow(color: .black.opacity(0.1), radius: 4, y: 1)
  }

  private var background: Color {
    switch variant {
    case .outline:
      return color == .neutral ? theme.color("light-glass-20") : theme.color("\\(color.rawValue)-1")
    case .filled:
      return color == .neutral ? theme.color("light-glass-20") : theme.color("\\(color.rawValue)-4")
    }
  }

  private var border: Color {
    switch variant {
    case .outline:
      return color == .neutral ? theme.color("light-glass-40") : theme.color("\\(color.rawValue)-3")
    case .filled:
      return .clear
    }
  }

  private var foreground: Color {
    switch variant {
    case .outline:
      return color == .neutral ? theme.color("light-space") : theme.color("\\(color.rawValue)-4")
    case .filled:
      switch color {
      case .green, .yellow: return theme.color("dark-space")
      default: return theme.color("light-space")
      }
    }
  }
}
`;
}

function renderSwitch() {
  return `${GENERATED_HEADER}import SwiftUI
import GooeyFoundation

public struct GooeySwitch: View {
  @Binding public var isOn: Bool
  public var label: String
  public var showsLabel: Bool
  public var isDisabled: Bool

  public init(
    isOn: Binding<Bool>,
    label: String,
    showsLabel: Bool = false,
    isDisabled: Bool = false
  ) {
    self._isOn = isOn
    self.label = label
    self.showsLabel = showsLabel
    self.isDisabled = isDisabled
  }

  public var body: some View {
    HStack(spacing: 10) {
      if showsLabel {
        Text(label)
      }
      Toggle("", isOn: $isOn)
        .toggleStyle(GooeySwitchStyle())
        .labelsHidden()
    }
    .disabled(isDisabled)
    .accessibilityLabel(Text(label))
  }
}

public struct GooeySwitchStyle: ToggleStyle {
  @Environment(\\.gooeyTheme) private var theme
  @Environment(\\.gooeyHaptics) private var haptics
  @Environment(\\.accessibilityReduceMotion) private var reduceMotion

  public init() {}

  public func makeBody(configuration: Configuration) -> some View {
    Button {
      haptics.light()
      configuration.isOn.toggle()
    } label: {
      RoundedRectangle(cornerRadius: 24, style: .continuous)
        .fill(configuration.isOn ? theme.color("blue-5") : theme.color("light-glass-5"))
        .frame(width: 64, height: 40)
        .overlay(alignment: configuration.isOn ? .trailing : .leading) {
          Circle()
            .fill(configuration.isOn ? theme.color("light-space") : theme.color("smoke-4"))
            .frame(width: 30, height: 30)
            .overlay {
              Circle().stroke(configuration.isOn ? theme.color("dark-glass-10") : theme.color("light-glass-20"), lineWidth: 2)
            }
            .padding(3)
        }
        .overlay {
          RoundedRectangle(cornerRadius: 24, style: .continuous)
            .stroke(configuration.isOn ? theme.color("light-glass-40") : theme.color("light-glass-10"), lineWidth: 2)
        }
    }
    .buttonStyle(PlainButtonStyle())
    .animation(reduceMotion ? nil : .spring(response: 0.28, dampingFraction: 0.72), value: configuration.isOn)
  }
}
`;
}

