function renderSelectionControl({ typeName, shape, roleText }) {
  return `${GENERATED_HEADER}import SwiftUI
import GooeyFoundation

public struct ${typeName}: View {
  @Binding public var isOn: Bool
  public var label: String
  public var isDisabled: Bool

  @Environment(\\.gooeyTheme) private var theme
  @Environment(\\.gooeyHaptics) private var haptics
  @Environment(\\.accessibilityReduceMotion) private var reduceMotion

  public init(
    isOn: Binding<Bool>,
    label: String,
    isDisabled: Bool = false
  ) {
    self._isOn = isOn
    self.label = label
    self.isDisabled = isDisabled
  }

  public var body: some View {
    Button {
      haptics.selection()
      isOn.toggle()
    } label: {
      ZStack {
        ${shape}
          .stroke(theme.color("light-space"), lineWidth: 1.5)
          .frame(width: 13, height: 13)

        if isOn {
          ${shape}
            .fill(theme.color("blue-4"))
            .frame(width: 7, height: 7)
            .transition(.scale.combined(with: .opacity))
        }
      }
      .frame(minWidth: 44, minHeight: 44)
      .contentShape(Rectangle())
    }
    .buttonStyle(PlainButtonStyle())
    .disabled(isDisabled)
    .opacity(isDisabled ? 0.5 : 1)
    .accessibilityLabel(Text(label))
    .accessibilityValue(Text(isOn ? "Selected" : "Not selected"))
    .accessibilityAddTraits(${roleText === "checkbox" ? ".isButton" : ".isButton"})
    .animation(reduceMotion ? nil : .spring(response: 0.22, dampingFraction: 0.8), value: isOn)
  }
}
`;
}

