function renderSkeleton() {
  return `${GENERATED_HEADER}import SwiftUI
import GooeyFoundation

public enum GooeySkeletonVariant: Sendable {
  case \`default\`
  case conversation
  case avatar
  case text
}

public struct GooeySkeleton: View {
  public var variant: GooeySkeletonVariant
  public var width: CGFloat?
  public var height: CGFloat?

  @Environment(\\.gooeyTheme) private var theme
  @Environment(\\.accessibilityReduceMotion) private var reduceMotion

  public init(
    variant: GooeySkeletonVariant = .default,
    width: CGFloat? = nil,
    height: CGFloat? = nil
  ) {
    self.variant = variant
    self.width = width
    self.height = height
  }

  public var body: some View {
    RoundedRectangle(cornerRadius: cornerRadius, style: .continuous)
      .fill(fillColor)
      .frame(width: resolvedWidth, height: resolvedHeight)
      .opacity(reduceMotion ? 1 : pulseOpacity)
      .animation(reduceMotion ? nil : .easeInOut(duration: 1.2).repeatForever(autoreverses: true), value: pulseOpacity)
      .onAppear {
        if !reduceMotion {
          pulseOpacity = 0.55
        }
      }
      .accessibilityHidden(true)
  }

  @State private var pulseOpacity: Double = 1

  private var cornerRadius: CGFloat {
    switch variant {
    case .default: return 6
    case .conversation, .avatar: return 999
    case .text: return 4
    }
  }

  private var resolvedWidth: CGFloat? {
    if let width { return width }
    if variant == .avatar { return 42 }
    return nil
  }

  private var resolvedHeight: CGFloat? {
    if let height { return height }
    switch variant {
    case .avatar: return 42
    case .text: return 14
    default: return nil
    }
  }

  private var fillColor: Color {
    switch theme.resolvedScheme {
    case .dark:
      return Color.white.opacity(variant == .default ? 0.05 : 0.06)
    case .light:
      return Color.black.opacity(variant == .default ? 0.05 : 0.04)
    }
  }
}
`;
}

function addReport(writes, outDir, conversion, selected, tokenSets) {
  const supported = [...SUPPORTED_COMPONENTS.keys()].sort();
  const report = {
    schemaVersion: 1,
    generatedAt: new Date().toISOString(),
    sourceRoot: ROOT,
    selectedComponents: selected,
    tokenCounts: {
      dark: Object.keys(tokenSets.dark).length,
      light: Object.keys(tokenSets.light).length,
    },
    totals: {
      components: conversion.length,
      templateReady: conversion.filter((item) => item.status === "template-ready").length,
      converted: conversion.filter((item) => item.status === "converted").length,
      needsTemplate: conversion.filter((item) => item.status === "needs-template").length,
      swiftTemplates: supported.length,
    },
    components: conversion,
  };

  const manifest = {
    schemaVersion: 1,
    generatedAt: report.generatedAt,
    sourceOfTruth: {
      tokens: "packages/gooey/src/styles/design-tokens.css",
      reactComponents: "packages/gooey/src/components/ui",
    },
    platforms: {
      react: {
        package: "@jokuh/gooey",
        path: "packages/gooey",
        targets: ["web", "react-native"],
      },
      swift: {
        package: "GooeySwift",
        path: "swift/GooeySwift",
        targets: ["ios", "macos"],
        spmProduct: "GooeySwift",
      },
      android: {
        primary: "@jokuh/gooey",
        note: "Use React Native with @jokuh/gooey for Android UI parity until a native Compose track exists.",
      },
    },
    swiftSupportedComponents: supported,
    parity: conversion
      .filter((item) => SUPPORTED_COMPONENTS.has(item.id))
      .map((item) => ({
        id: item.id,
        react: item.source,
        swift: item.swiftFile,
        status: item.status,
      })),
  };

  setWrite(
    writes,
    path.join(outDir, "swift-conversion-report.json"),
    `${JSON.stringify(report, null, 2)}\n`,
  );
  setWrite(
    writes,
    path.join(outDir, "platform-manifest.json"),
    `${JSON.stringify(manifest, null, 2)}\n`,
  );
}

function setWrite(writes, filePath, contents) {
  writes.set(filePath, contents);
}

function writeAll(writes, { force }) {
  for (const [filePath, contents] of writes) {
    if (existsSync(filePath) && !force && !isGeneratedFile(filePath)) {
      fail(`Refusing to overwrite non-generated file: ${path.relative(ROOT, filePath)}. Use --force only after reviewing it.`);
    }
    mkdirSync(path.dirname(filePath), { recursive: true });
    writeFileSync(filePath, contents);
  }
}

function isGeneratedFile(filePath) {
  try {
    const existing = readFileSync(filePath, "utf8");
    if (filePath.endsWith("swift-conversion-report.json") || filePath.endsWith("platform-manifest.json")) {
      return true;
    }
    return existing.includes("Generated by scripts/convert-gooey-swift.mjs");
  } catch {
    return false;
  }
}

function printComponentList(conversion) {
  const ready = conversion.filter((item) => item.status === "template-ready");
  const blocked = conversion.filter((item) => item.status === "needs-template");

  console.log(`Template-ready components (${ready.length}):`);
  for (const item of ready) {
    console.log(`  ${item.id} -> ${item.target}`);
  }

  console.log(`\nNeeds template or adapter (${blocked.length}):`);
  for (const item of blocked) {
    console.log(`  ${item.id}: ${item.reason}`);
  }
}

function printDryRun(writes, conversion, selected, outDir) {
  console.log(`Dry run output root: ${path.relative(ROOT, outDir)}`);
  console.log(`Selected components: ${selected.length ? selected.join(", ") : "none"}`);
  console.log(`Writable files: ${writes.size}`);
  for (const filePath of writes.keys()) {
    console.log(`  ${path.relative(ROOT, filePath)}`);
  }
  console.log(`Components still needing templates: ${conversion.filter((item) => item.status === "needs-template").length}`);
}

function printSummary(conversion, selected, outDir) {
  console.log(`Generated Gooey Swift package at ${path.relative(ROOT, outDir)}`);
  console.log(`Converted components: ${selected.length ? selected.join(", ") : "none"}`);
  console.log(`Template-ready remaining: ${conversion.filter((item) => item.status === "template-ready").length}`);
  console.log(`Needs template or native adapter: ${conversion.filter((item) => item.status === "needs-template").length}`);
  console.log(`Report: ${path.relative(ROOT, path.join(outDir, "swift-conversion-report.json"))}`);
}

function slugify(value) {
  return value
    .trim()
    .replace(/([a-z0-9])([A-Z])/g, "$1-$2")
    .replace(/_/g, "-")
    .toLowerCase();
}

function fail(message) {
  console.error(`convert-gooey-swift: ${message}`);
  process.exit(1);
}

main();
